          <meshStandardMaterial color="#dfd3a6" roughness={1} />
        </mesh>
        <mesh position={[0, -0.07, 0]} receiveShadow>
          <cylinderGeometry args={[8.55, 8.6, 0.12, 80]} />
          <meshStandardMaterial color={environment.ground} roughness={1} />
